    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 2000), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of cart lines", () => {
      const cart = new Cart();
      const prod = mkProduct("a", 1000);
      cart.add(prod, 2);
      const snap = cart.snapshot();
      // Mutating snapshot should not affect cart
      (snap as CartLine[])[0]!.quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2); // 2000
      cart.add(mkProduct("b", 500), 3); // 1500
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3500);
    });

    it("applies discount, then tax on discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(1000),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(400),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
      });
      cart.add(mkProduct("a", 5000), 1); // subtotal 5000
      const t = cart.totals();

      expect(t.subtotalCents).toBe(5000);
      expect(t.discountCents).toBe(1000);
      // Tax should be called with discounted subtotal (5000 - 1000 = 4000)
      expect(tax.computeTaxCents).toHaveBeenCalledWith(4000, "US");
      expect(t.taxCents).toBe(400);
      // total = 4000 + 400 + 0 shipping = 4400
      expect(t.totalCents).toBe(4400);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
      expect(t.totalCents).toBe(0); // nothing left
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("shipping receives discounted subtotal and lines", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();

      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // 1000 - 200
      );
      expect(t.shippingCents).toBe(599);
      expect(t.totalCents).toBe(800 + 599); // discounted + shipping, no tax
    });

    it("uses default config (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 2500), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(5000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(5000);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("uses provided region for tax calculation", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(mkProduct("a", 1000), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 2000), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(4000);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher before computing totals", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1500) // a: was 1000 → 1500
          .mockResolvedValueOnce(2500), // b: was 2000 → 2500
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal = 1500*2 + 2500*1 = 5500
      expect(result.totals.subtotalCents).toBe(5500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("checks inventory and throws InventoryError on denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
      }
    });

    it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // less than requested 2
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("passes when availableQuantity meets or exceeds requested", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 10,
        }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
    });

    it("passes when decision is available without availableQuantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 4000, no discount, tax = 10% of 4000 = 400
      expect(result.totals.taxCents).toBe(400);
      expect(result.totals.totalCents).toBe(4400);
    });

    it("combines priceFetcher + asyncTaxProvider + discount", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };
      const cartWithPolicies = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cartWithPolicies.add(mkProduct("x", 3000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(3500),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cartWithPolicies.checkout({
        priceFetcher,
        asyncTaxProvider,
      });

      // subtotal = 3500 * 2 = 7000
      // discount = 500 (clamped)
      // discounted = 6500
      // tax = 8% of 6500 = 520
      // shipping = 300
      expect(result.totals.subtotalCents).toBe(7000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(520);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(6500 + 520 + 300);
    });

    it("propagates asyncTaxProvider failure", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("propagates priceFetcher failure", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("pricing service unavailable")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "pricing service unavailable",
      );
    });

    it("uses sync tax calculator when no asyncTaxProvider given", async () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(200),
      };
      const cartWithTax = new Cart({ taxCalculator: tax });
      cartWithTax.add(mkProduct("a", 1000), 1);
      const result = await cartWithTax.checkout();
      expect(result.totals.taxCents).toBe(200);
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.0 (exact), 33% of 101 = 33.33 → 33
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when discount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // Each sees the original 10000: 1000 + 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so total is still just from the percentage
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1000);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000 → remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900  → remaining 8100
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("caps each step at remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(8000), // takes 8000, remaining 2000
          new FixedAmountDiscountPolicy(5000), // capped at 2000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 500 first, then 10% of remainder
      const fixedFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% first (1000), then fixed 500
      const pctFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );

      const subtotal = 10000;
      // fixedFirst: 500 + 10% of 9500 = 500 + 950 = 1450
      expect(fixedFirst.computeDiscountCents(subtotal)).toBe(1450);
      // pctFirst: 1000 + 500 = 1500
      expect(pctFirst.computeDiscountCents(subtotal)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

