describe("refreshPrices", () => {
  const mkLine = (id: string, price: number, qty = 1): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines = [mkLine("a", 1000), mkLine("b", 2000)];
    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(1500);
    expect(refreshed[1]!.product.unitPriceCents).toBe(2500);
    expect(refreshed[0]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 500, weightGrams: 200, currency: "EUR" },
        quantity: 3,
      },
    ];
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0]!.product.name).toBe("Widget");
    expect(refreshed[0]!.product.weightGrams).toBe(200);
    expect(refreshed[0]!.product.currency).toBe("EUR");
    expect(refreshed[0]!.quantity).toBe(3);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      "service down",
    );
  });

  it("returns empty array for empty lines", async () => {
