    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 2000), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(4000);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher before computing totals", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1500) // a: was 1000 → 1500
          .mockResolvedValueOnce(2500), // b: was 2000 → 2500
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal = 1500*2 + 2500*1 = 5500
      expect(result.totals.subtotalCents).toBe(5500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("checks inventory and throws InventoryError on denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
      }
    });

    it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // less than requested 2
        }),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("passes when availableQuantity meets or exceeds requested", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 10,
        }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
    });

    it("passes when decision is available without availableQuantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(4000);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 4000, no discount, tax = 10% of 4000 = 400
      expect(result.totals.taxCents).toBe(400);
      expect(result.totals.totalCents).toBe(4400);
    });

    it("combines priceFetcher + asyncTaxProvider + discount", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };
      const cartWithPolicies = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cartWithPolicies.add(mkProduct("x", 3000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(3500),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cartWithPolicies.checkout({
        priceFetcher,
        asyncTaxProvider,
      });

      // subtotal = 3500 * 2 = 7000
      // discount = 500 (clamped)
      // discounted = 6500
      // tax = 8% of 6500 = 520
      // shipping = 300
      expect(result.totals.subtotalCents).toBe(7000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(520);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(6500 + 520 + 300);
    });

    it("propagates asyncTaxProvider failure", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("propagates priceFetcher failure", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("pricing service unavailable")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "pricing service unavailable",
      );
    });

    it("uses sync tax calculator when no asyncTaxProvider given", async () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(200),
      };
      const cartWithTax = new Cart({ taxCalculator: tax });
      cartWithTax.add(mkProduct("a", 1000), 1);
      const result = await cartWithTax.checkout();
      expect(result.totals.taxCents).toBe(200);
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });
});
