toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const noWeightLine = (id: string, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flatCents for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line("a", 100)], 3000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 6000)).toBe(0);
    });

    it("returns flatCents when subtotal is below freeOverCents", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 4999)).toBe(599);
    });

    it("returns flatCents when no threshold is configured", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line("a", 100)], 100000)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 1.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(
        calc.computeShippingCents([noWeightLine("a")], 5000),
      ).toBe(0);
    });

    it("selects first bracket when weight is within", () => {
      // 500g total, within first bracket
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // Exactly 2000g → second bracket
      expect(
        calc.computeShippingCents([line("a", 1000, 2)], 5000),
      ).toBe(700);
    });

    it("selects next bracket just past boundary", () => {
      // 501g → second bracket
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(700);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 6000g → overflow
      expect(
        calc.computeShippingCents([line("a", 3000, 2)], 5000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 2000g → last bracket cost = 600
      expect(
        noOverflow.computeShippingCents([line("a", 2000)], 5000),
      ).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → should hit 500g bracket = 300
      expect(
        unordered.computeShippingCents([line("a", 400)], 5000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 300*2 + 200*1 = 800g → second bracket (501-2000)
      expect(
        calc.computeShippingCents(
          [line("a", 300, 2), line("b", 200)],
          5000,
        ),
      ).toBe(700);
    });
  });
});

